{
  "name": "opencode-retry-forever",
  "version": "0.1.0",
  "description": "Keeps long-running opencode sessions alive by retrying transient provider failures (503, DNS, connection resets) forever, with no backoff.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "retry",
    "resilience"
  ],
  "license": "MIT",
  "author": "Aryan Randeriya <aryan.k.randeriya@gmail.com>",
  "homepage": "https://github.com/aryanranderiya/opencode-retry-forever#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aryanranderiya/opencode-retry-forever.git"
  },
  "bugs": {
    "url": "https://github.com/aryanranderiya/opencode-retry-forever/issues"
  },
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.2",
    "typescript": "^5.7.2"
  }
}
